using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class Refine023 {
 public static object Main(){AssetDatabase.Refresh();var root=GameObject.Find("Island023");var t=root.GetComponentInChildren<Terrain>();var td=t.terrainData;int n=td.alphamapResolution;var a=new float[n,n,4];for(int z=0;z<n;z++)for(int x=0;x<n;x++){float px=x/(float)(n-1)*160-80,pz=z/(float)(n-1)*160-80;float s=(1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(-40,-26,pz)))*(1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(29,47,Mathf.Abs(px-5))));s=Mathf.Clamp01(s+(Mathf.PerlinNoise(px*.8f,pz*.8f)-.5f)*.15f);a[z,x,0]=1-s;a[z,x,3]=s;}td.SetAlphamaps(0,0,a);td.SetBaseMapDirty();EditorUtility.SetDirty(td);foreach(var tex in td.alphamapTextures)EditorUtility.SetDirty(tex);
 foreach(string model in Freyja.WorldBuilder.Editor.Island023.Plots.Select(p=>p.model).Distinct()){string path=Freyja.WorldBuilder.Editor.Island023.Folder+"/"+model+".prefab";var prefab=PrefabUtility.LoadPrefabContents(path);prefab.transform.GetChild(0).localRotation=Quaternion.Euler(0,180,0);PrefabUtility.SaveAsPrefabAsset(prefab,path);PrefabUtility.UnloadPrefabContents(prefab);}
 var road=AssetDatabase.LoadAssetAtPath<Material>(Freyja.WorldBuilder.Editor.Island023.Folder+"/RoadEdge.mat");road.mainTexture=Freyja.WorldBuilder.Editor.KitPS1.Material("PathSand").mainTexture;road.color=new Color(1,.9f,.76f);EditorUtility.SetDirty(road);
 var plaza=root.transform.Find("Ruas e caminhos/Praça central");var mesh=new Mesh();var vs=new Vector3[49];var uv=new Vector2[49];var tris=new int[48*3];vs[0]=new Vector3(0,6.055f,-9);uv[0]=Vector2.zero;for(int i=0;i<48;i++){float ang=i/48f*Mathf.PI*2;vs[i+1]=new Vector3(Mathf.Cos(ang)*13.5f,6.055f,-9+Mathf.Sin(ang)*8);uv[i+1]=new Vector2(vs[i+1].x,vs[i+1].z+9)/3;tris[i*3]=0;tris[i*3+1]=(i+1)%48+1;tris[i*3+2]=i+1;}mesh.vertices=vs;mesh.uv=uv;mesh.triangles=tris;mesh.RecalculateNormals();AssetDatabase.CreateAsset(mesh,Freyja.WorldBuilder.Editor.Island023.Folder+"/Plaza.asset");UnityEngine.Object.DestroyImmediate(plaza.GetComponent<Collider>());plaza.localScale=Vector3.one;plaza.position=Vector3.zero;plaza.GetComponent<MeshFilter>().sharedMesh=mesh;plaza.gameObject.AddComponent<MeshCollider>().sharedMesh=mesh;
 // Afastar rochas da casa isolada e liberar a chegada ao cais.
 foreach(Transform prop in root.transform.Find("Pedras e árvores editáveis")){if(prop.name.StartsWith("Rock")&&(Vector2.Distance(new Vector2(prop.position.x,prop.position.z),new Vector2(-52,43))<8||Vector2.Distance(new Vector2(prop.position.x,prop.position.z),new Vector2(-38,-54))<9))prop.gameObject.SetActive(false);}
 AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(root.scene);return new {buildings=root.transform.Find("Construções — 12 casas e 5 serviços").childCount,beachWeight=td.GetAlphamaps(n/2,n/6,1,1)[0,0,3]};}
}
